const digest = (bytes) => createHash('sha256').update(bytes).digest('hex')
async function fixture(run) {
  const parent = await realpath(tmpdir()),
    directory = await mkdtemp(join(parent, 'frade-vscode-contract-'))
  const owner = await stat(directory, { bigint: true })
  const put = async (name, value) => {
    const target = resolve(directory, name)
    assert(!relative(directory, target).startsWith('..'))
    await mkdir(dirname(target), { recursive: true })
    await writeFile(target, value)
  }
  try {
    for (const name of [
      '2026-dark.json',
      'dark_modern.json',
      'dark_plus.json',
      'dark_vs.json',
      'LICENSE.txt',
    ]) {
      const file = referenceDirectory + '/upstream/' + name
      await put(file, await readFile(resolve(root, file)))
    }
    for (const file of [
      referenceDirectory + '/.gitattributes',
      generatedPath,
      'packages/ui-workspace/tokens/tokens.json',
    ])
      await put(file, await readFile(resolve(root, file)))
    await run({ directory, put })
  } finally {
    const actual = await realpath(directory),
      current = await stat(actual, { bigint: true })
    assert.equal(dirname(actual), parent)
    assert(actual.startsWith(join(parent, 'frade-vscode-contract-')))
    assert.equal(current.ino, owner.ino)
    assert.equal(current.dev, owner.dev)
    await rm(actual, { recursive: true })
  }
}
function git(cwd, args) {
  const result = spawnSync(
    'git',
    [
      '-c',
      'core.longpaths=true',
      '-c',
      'maintenance.auto=false',
      '-c',
      'gc.auto=0',
      '-c',
      'commit.gpgSign=false',
      ...args,
    ],
    { cwd, encoding: 'utf8', windowsHide: true, timeout: 30000 },
  )
  assert.equal(result.status, 0, result.stderr + result.stdout)
  return result.stdout
}

